import React, { useEffect, useRef, useState } from "react";

function cardsPerView() {
  if (window.matchMedia("(max-width: 640px)").matches) {
    return 1;
  }
  if (window.matchMedia("(max-width: 960px)").matches) {
    return 2;
  }
  return 3;
}

export default function NewsSlider({ items }) {
  const [perView, setPerView] = useState(3);
  const [index, setIndex] = useState(0);
  const drag = useRef(null);
  const pageCount = Math.max(1, items.length - perView + 1);
  const showControls = pageCount > 1;

  useEffect(() => {
    const update = () => setPerView(cardsPerView());
    update();
    window.addEventListener("resize", update);
    return () => window.removeEventListener("resize", update);
  }, []);

  useEffect(() => {
    setIndex((current) => Math.min(current, Math.max(0, items.length - perView)));
  }, [items.length, perView]);

  function go(next) {
    setIndex((current) => {
      const max = Math.max(0, items.length - perView);
      return Math.min(max, Math.max(0, next));
    });
  }

  function onKeyDown(event) {
    if (event.key === "ArrowRight") {
      event.preventDefault();
      go(index + 1);
    }
    if (event.key === "ArrowLeft") {
      event.preventDefault();
      go(index - 1);
    }
  }

  function onPointerDown(event) {
    drag.current = { x: event.clientX, id: event.pointerId };
  }

  function onPointerUp(event) {
    if (!drag.current || drag.current.id !== event.pointerId) {
      return;
    }
    const delta = event.clientX - drag.current.x;
    drag.current = null;
    if (delta <= -48) {
      go(index + 1);
    } else if (delta >= 48) {
      go(index - 1);
    }
  }

  const start = index + 1;
  const end = Math.min(index + perView, items.length);

  return (
    <div
      className="news-slider"
      role="region"
      aria-roledescription="carousel"
      aria-label="Latest news"
      tabIndex={0}
      onKeyDown={onKeyDown}
    >
      <p className="visually-hidden" aria-live="polite">
        Showing announcements {start} to {end} of {items.length}.
      </p>
      <div
        className="news-viewport"
        onPointerDown={onPointerDown}
        onPointerUp={onPointerUp}
        onPointerCancel={() => {
          drag.current = null;
        }}
      >
        <ul
          className="news-track"
          style={{
            width: `${(items.length / perView) * 100}%`,
            transform: `translateX(-${(index * 100) / items.length}%)`,
          }}
        >
          {items.map((item) => (
            <li
              className="news-card"
              key={item.id}
              style={{ flexBasis: `${100 / items.length}%` }}
            >
              <article>
                <p className="meta">{item.displayDate}</p>
                <h3>{item.title}</h3>
                <p>{item.description}</p>
                {item.links.length ? (
                  <ul className="resource-links">
                    {item.links.map((link) => (
                      <li key={link.href}>
                        <a href={link.href} target="_blank" rel="noopener noreferrer">
                          {link.label}
                        </a>
                      </li>
                    ))}
                  </ul>
                ) : null}
              </article>
            </li>
          ))}
        </ul>
      </div>
      {showControls ? (
        <div className="slider-controls">
          <button
            type="button"
            className="slider-arrow"
            aria-label="Previous announcements"
            onClick={() => go(index - 1)}
            disabled={index === 0}
          >
            Previous
          </button>
          <div className="slider-dots" role="group" aria-label="News pages">
            {Array.from({ length: pageCount }, (_, dot) => (
              <button
                type="button"
                key={dot}
                className={dot === index ? "slider-dot is-active" : "slider-dot"}
                aria-label={`Show announcements starting at ${dot + 1}`}
                aria-current={dot === index ? "true" : undefined}
                onClick={() => go(dot)}
              />
            ))}
          </div>
          <button
            type="button"
            className="slider-arrow"
            aria-label="Next announcements"
            onClick={() => go(index + 1)}
            disabled={index >= pageCount - 1}
          >
            Next
          </button>
        </div>
      ) : null}
    </div>
  );
}
